#!/usr/bin/env python3
"""Builds reading-list.json (the 2026-27 independent-reading plan shown on the Library page).
Each Project Gutenberg book page was confirmed on 2026-10-23. Re-run tools/build-enrichment-2026-10.py afterwards so lesson plans pick up changes."""
import json, urllib.parse
G = lambda n: {"label": "Read free (Project Gutenberg)", "url": f"https://www.gutenberg.org/ebooks/{n}", "type": "ebook"}
H = lambda n: {"label": "Read online", "url": f"https://www.gutenberg.org/cache/epub/{n}/pg{n}-images.html", "type": "web"}
W = lambda q: {"label": "Find at your library", "url": "https://search.worldcat.org/search?q=" + urllib.parse.quote(q), "type": "library"}
M = {1:("Oct 12 – Nov 6","Module 1"),2:("Nov 9 – Dec 11","Module 2"),3:("Dec 14 – Jan 22","Module 3"),4:("Jan 25 – Feb 19","Module 4"),
     5:("Feb 22 – Mar 26","Module 5"),6:("Mar 29 – Apr 23","Module 6"),7:("Apr 26 – May 21","Module 7"),8:("May 24 – Jun 18","Module 8"),9:("Jun 21 – Jul 16","Module 9")}
SE={1:("2026-10-12","2026-11-06"),2:("2026-11-09","2026-12-11"),3:("2026-12-14","2027-01-22"),4:("2027-01-25","2027-02-19"),5:("2027-02-22","2027-03-26"),6:("2027-03-29","2027-04-23"),7:("2027-04-26","2027-05-21"),8:("2027-05-24","2027-06-18"),9:("2027-06-21","2027-07-16")}
def book(id, module, title, author, year, n, why, ties, prompts, note="", role="core", pages=None, html=True):
    d = dict(id=id, module=module, dates=M[module][0], role=role, title=title, author=author, year=year, why=why, ties=ties,
             prompts=prompts, note=note, access="Free · public domain", links=[G(n)] + ([H(n)] if html else []))
    if pages: d["length"] = pages
    return d
def lib(id, title, author, why, modules, note=""):
    return dict(id=id, title=title, author=author, why=why, modules=modules, note=note, access="Free with a library card (print, Libby or Hoopla)", links=[W(f"{title} {author}")])

